"""Product analytics dashboard: conversion statistics over customer sessions."""


def conversion_rate(events):
    """The conversion rate of a list of sessions. See SPEC.md section 1."""
    if not events:
        return 0.0
    hits = sum(1 for e in events if e["converted"] is True)
    return hits / len(events)


def pooled_conversion_rate(groups):
    """The pooled conversion rate across groups of sessions. See SPEC.md section 2."""
    total = sum(len(events) for events in groups.values())
    if not total:
        return 0.0
    hits = sum(1 for events in groups.values() for e in events if e["converted"] is True)
    return hits / total


def conversions_in_window(daily_counts, days):
    """Sum over a trailing window of daily counts. See SPEC.md section 3."""
    if days <= 0:
        return 0
    return sum(daily_counts[-days:])


def conversion_rate_by_group(groups):
    """The conversion rate of each group. See SPEC.md section 9."""
    return {
        name: conversion_rate(groups[name]) if groups[name] else None
        for name in sorted(groups)
    }


def longest_conversion_streak(daily_counts):
    """Longest run of days with converted sessions. See SPEC.md section 10."""
    best = cur = 0
    for count in daily_counts:
        if count > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

"""Product analytics dashboard: conversion statistics over customer sessions."""


def parse_session_log(lines):
    """Parse log lines into sessions. See SPEC.md section 4."""
    out = []
    flags = {"1": True, "0": False, "": None}
    for line_number, line in enumerate(lines, 1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected three fields")
        id_, day, flag = fields
        try:
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: invalid day") from exc
        if flag not in flags:
            raise ValueError(f"line {line_number}: invalid converted value")
        out.append({"id": id_, "day": day, "converted": flags[flag]})
    return out


def dedupe_sessions(events):
    """Remove duplicate sessions. See SPEC.md section 5."""
    seen = {}
    for e in events:
        seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Daily counts of converted sessions. See SPEC.md section 6."""
    if end_day < start_day:
        return []
    counts = [0] * (end_day - start_day + 1)
    for e in events:
        if start_day <= e["day"] <= end_day and e["converted"] is True:
            counts[e["day"] - start_day] += 1
    return counts

import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_in_denominator():
    assert conversion_rate([session("a", 1, True), session("b", 1, None)]) == 0.5
    assert conversion_rate([session("a", 1, None)]) == 0.0
    assert conversion_rate([]) == 0.0


def test_pooled_rate_weights_each_session_and_handles_empty_groups():
    groups = {"a": [session("a", 1, True)], "b": [session("b", 1, False)] * 3, "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({}) == 0.0
    assert pooled_conversion_rate({"empty": []}) == 0.0


def test_conversions_in_window():
    assert conversions_in_window([1, 2, 3], 0) == 0
    assert conversions_in_window([1, 2, 3], 1) == 3
    assert conversions_in_window([1, 2, 3], 2) == 5
    assert conversions_in_window([1, 2, 3], 10) == 6
    assert conversions_in_window([], 2) == 0


def test_parse_session_log_fields_and_skipped_lines():
    lines = ["\n", "  # comment, ignored\n", " a , 2 , 1 ", "b, 3, 0", "c, -1,  "]
    assert parse_session_log(lines) == [
        session("a", 2, True), session("b", 3, False), session("c", -1, None)
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1,yes"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_session_log(["  ", " # comment", bad_line])


def test_dedupe_sessions_keeps_last_duplicate_and_sorts_by_day_and_id():
    events = [session("b", 1, True), session("a", 3, True), session("b", 3, False),
              session("c", 2, None), session("a", 3, False)]
    assert dedupe_sessions(events) == [events[3], events[4], events[2]]
    assert dedupe_sessions([]) == []


def test_daily_counts_include_empty_days_and_ignore_outside_range():
    events = [session("a", 0, True), session("b", 2, True), session("c", 2, True),
              session("d", 3, False), session("e", 4, None), session("f", 5, True)]
    assert daily_conversion_counts(events, 1, 4) == [0, 2, 0, 0]
    assert daily_conversion_counts([], 1, 3) == [0, 0, 0]
    assert daily_conversion_counts(events, 4, 1) == []


def test_campaign_summary_uses_calendar_days_pooled_rate_and_nonempty_groups():
    groups = {"a": [session("a", 1, True)],
              "b": [session("b", 3, True), session("c", 5, False)], "empty": []}
    assert campaign_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 0)["recent"] == 0
    assert campaign_summary(groups, 10)["recent"] == 2
    assert campaign_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [session("z", 1, True)], "empty": [],
              "b": [session("b", 1, True)], "a": [session("a", 1, False)]}
    assert top_converting_groups(groups, 2) == ["b", "z"]
    assert top_converting_groups(groups, 10) == ["b", "z", "a"]
    assert top_converting_groups(groups, 0) == []


def test_conversion_rate_by_group_includes_empty_groups_sorted():
    groups = {"z": [], "b": [session("b", 1, None)], "a": [session("a", 1, True)]}
    rates = conversion_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_conversion_streak_resets_on_nonpositive_counts():
    assert longest_conversion_streak([1, 2, 0, 3, -1, 1, 1, 1]) == 3
    assert longest_conversion_streak([0, -1]) == 0
    assert longest_conversion_streak([]) == 0
